/bin/zsh -lc "python3 - <<'PY'
import sys, json, random
sys.path.insert(0, 'source')
from ledger import summarize
rng = random.Random(731)
cases = [None, {}, [None], [{'key':'x'}], [{'key':'x','amount':'1\\n'}]]
for _ in range(400):
    rows = []
    for _ in range(rng.randrange(15)):
        row = {'key': rng.choice(['a','b','','__proto__','2','10','é']), 'amount': str(rng.randrange(-10**60,10**60))}
        if rng.random() < .8: row['priority'] = rng.choice([None,-1000,0,100,1000,False,'1',1001])
        if rng.random() < .1: row['amount'] = rng.choice(['1.5','1\\n','١','+0001','-0'])
        rows.append(row)
    cases.append(rows)
fixtures=[]
for rows in cases:
    try: result={'value':summarize(rows)}
    except ValueError as e: result={'error':str(e)}
    fixtures.append({'rows':rows, 'expected':result})
with open('.ledger-parity.json','w') as f: json.dump(fixtures,f)
print('Generated',len(fixtures),'Python oracle cases')
print('Python decimal conversion limit:',sys.get_int_max_str_digits())
for priority in [1.0, True]:
    try: print('priority',repr(priority),summarize([{'key':'a','amount':'1','priority':priority}]))
    except ValueError as e: print('priority',repr(priority),'error:',str(e))
PY"

